func (e *Editor) KeyUp() {
    if e.line.Prev() != e.lines.End() {
        col := e.getColumn()
        e.line = e.line.Prev()
        e.cursor = e.getCharAt(e.line.Value, col)
    }
}

func (e *Editor) KeyDown() {
    if e.line.Next() != e.lines.End() {
        col := e.getColumn()
        e.line = e.line.Next()
        e.cursor = e.getCharAt(e.line.Value, col)
    }
}

